import{_ as a,o as e,c as i,a3 as n}from"./chunks/framework.d6OaePA7.js";const h=JSON.parse('{"title":"Lite工具简单排查","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://scattter.github.io/pages/explore/frontend/Lite%E5%B7%A5%E5%85%B7%E7%AE%80%E5%8D%95%E6%8E%92%E6%9F%A5.html"}]]},"headers":[],"relativePath":"pages/explore/frontend/Lite工具简单排查.md","filePath":"pages/explore/frontend/Lite工具简单排查.md","lastUpdated":1789275801000}'),o={name:"pages/explore/frontend/Lite工具简单排查.md"};function m(p,t,g,s,d,r){return e(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="lite工具简单排查" tabindex="-1">Lite工具简单排查 <a class="header-anchor" href="#lite工具简单排查" aria-label="Permalink to &quot;Lite工具简单排查&quot;">​</a></h1><p>以 <strong><a href="https://sit.meijian.com/mj/meijian-tool/meijian-platform/lite-design?configId&amp;designId=1039855&amp;subSiteFrom=default" target="_blank" rel="noreferrer">此方案</a></strong> 为基准测试</p><blockquote><p>优化前性能截图待补充。</p></blockquote><p>主要问题在于移动端打开lite工具的时候页面十分卡顿</p><ol><li>事件监听多?</li><li>引入的额外资源比较多</li><li>内存占用过高</li><li>监听过多</li></ol><p>由于是在移动端使用, 不属于重度使用场景, 更多的重点在于能支持一些简单, 临时的修改就行, 因此主要优化原则就是 <strong>能精简就精简</strong>.</p><p>简单处理后得分</p><blockquote><p>优化后性能截图待补充。</p></blockquote><p><strong>内存占用过高</strong>(暂时未排查到具体点, 后续做的时候再排查下)</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image2025-8-19_9-45-4.png" alt="image2025-8-19_9-45-4"></p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image2025-8-19_11-27-40.png" alt="image2025-8-19_11-27-40"></p><p><a href="https://developer.chrome.com/docs/lighthouse/performance/mainthread-work-breakdown?utm_source=lighthouse&amp;utm_medium=devtools&amp;hl=zh-cn" target="_blank" rel="noreferrer">https://developer.chrome.com/docs/lighthouse/performance/mainthread-work-breakdown?utm_source=lighthouse&amp;utm_medium=devtools&amp;hl=zh-cn</a></p><p><a href="https://web.dev/articles/monitor-total-page-memory-usage?hl=zh-cn" target="_blank" rel="noreferrer">https://web.dev/articles/monitor-total-page-memory-usage?hl=zh-cn</a></p><h2 id="部分已处理问题记录如下" tabindex="-1">部分已处理问题记录如下 <a class="header-anchor" href="#部分已处理问题记录如下" aria-label="Permalink to &quot;部分已处理问题记录如下&quot;">​</a></h2><table tabindex="0"><thead><tr><th>示例</th><th>具体问题</th><th>解决方法</th></tr></thead><tbody><tr><td><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image2025-8-18_17-17-28.png" alt="image2025-8-18_17-17-28" style="zoom:25%;"></td><td>export-design: 841kb, <br>右上角分享弹窗</td><td>懒加载, 点击右上角按钮再去加载</td></tr><tr><td></td><td>ai-generate: 953kb, <br>文本生成 (旧版文本生成)</td><td>同上懒加载方式</td></tr><tr><td></td><td>tool-ui-cmn: 788kb</td><td>不处理, 保持现状</td></tr><tr><td></td><td>字体资源<br>yanshixiaxingkai.woff2: 4657Kb<br>backupFont.woff2: 4176Kb<br>taiwanquanziku....woff2: 3809Kb<br>Source....woff2: 1013kb...</td><td>不处理, 保持现状</td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr></tbody></table><p>示例具体问题解决方法<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-18_17-17-28.png?version=1&amp;modificationDate=1755508649000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-18_17-17-28.png"> export-design: 841kb右上角分享弹窗懒加载, 点击右上角按钮再去加载ai-generate: 953kb文本生成 (旧版文本生成)同上懒加载方式tool-ui-cmn: 788kb不处理, 保持现状字体资源yanshixiaxingkai.woff2: 4657KbbackupFont.woff2: 4176Kbtaiwanquanziku....woff2: 3809KbSource....woff2: 1013kb...不处理, 保持现状tool-ui组件资源之前有部分toast使用的tools-ui, 现在统一为了mj-base-ui(这里mj-base里面不做替换)<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_16-11-51.png?version=1&amp;modificationDate=1755763911000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_16-11-51.png"><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_16-13-26.png?version=1&amp;modificationDate=1755764007000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_16-13-26.png">由于lite工具要支持多语言路径切换, 所以挂载了完整的多语言内容, 请求大小飙升至623k如果是pad端, 同时不是coohom环境, 是不是就可以先不适配多语言了(这样能节约很多)local<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_16-56-11.png?version=1&amp;modificationDate=1755766572000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_16-56-11.png">sit<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_16-55-56.png?version=1&amp;modificationDate=1755766557000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_16-55-56.png">lite工具没有chunk, 资源体积有4670ksit环境打包是用splitChunk + Terser<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_17-9-31.png?version=1&amp;modificationDate=1755767372000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_17-9-31.png">chunk拆分后为3801 + 894 两个请求<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_17-20-31.png?version=1&amp;modificationDate=1755768032000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_17-20-31.png">terser压缩后为3449 + 845两个请求, 相比于之前节约了376k</p><p>示例具体问题解决方法<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-18_18-10-33.png?version=1&amp;modificationDate=1755511834000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-18_18-10-33.png">空白页面icon集成到项目中, 不使用线上资源其他图片由于其他的都是预览图, 没办法提前获取, 因此不处理</p><p>示例具体问题解决方法<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-18_18-19-47.png?version=1&amp;modificationDate=1755512388000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-18_18-19-47.png">需要gzip处理暂不处理</p><p>示例具体问题解决方法<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-18_18-20-28.png?version=1&amp;modificationDate=1755512429000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-18_18-20-28.png"><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_15-45-3.png?version=1&amp;modificationDate=1755762303000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_15-45-3.png">返回的资源没有经过压缩使用css-minimizer-webpack-plugin 进行处理, 但是暂时看起来没生效返回了部分其他暂时不用的微应用的资源在第一part懒加载处理后也就不存在了</p><p>示例具体问题解决方法<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-20_15-11-43.png?version=1&amp;modificationDate=1755673904000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-20_15-11-43.png">部分图片请求没有走webp增加对imgUrl的webp处理<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-20_16-22-31.png?version=1&amp;modificationDate=1755678152000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-20_16-22-31.png"></p><p>最长的task: 820ms<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_18-1-41.png?version=1&amp;modificationDate=1755770502000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_18-1-41.png"><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_19-29-12.png?version=1&amp;modificationDate=1755775753000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_19-29-12.png"> 示例频繁触发函数 <code>触发layout/util.ts(这里是处理元素)186.4 + 59.7</code><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_17-51-1.png?version=1&amp;modificationDate=1755769861000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_17-51-1.png"><code>eliminateConstraintCollisionByTypealgorithm/layout/util.ts: 186.4KGxLayoutContainer: 108.4 (主要优化)DisplayEntities/index.ts: 49.3 (次要)intelligentContainerEntity/index.ts: 46.3IntelligentLayoutBuilderAdapter.ts: 37.5photoWallLayout.ts: 37.4</code> <img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_18-3-12.png?version=1&amp;modificationDate=1755770593000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_18-3-12.png"><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_11-10-6.png?version=1&amp;modificationDate=1755832207000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_11-10-6.png">IntelligentGroupCommand: 59.7icon-park 触发layout布局<img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_17-51-57.png?version=1&amp;modificationDate=1755769918000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_17-51-57.png">layout: 112.9FunctionPanel: 79QuickDesign: 14.7Design: 11.9AIBackground: 11.6AIAssitant: 26.3 <img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_17-55-15.png?version=1&amp;modificationDate=1755770116000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_17-55-15.png">sceneHandler: 77.6batchGenerate: 70.3BatchGeneratePanel: 46controlPoints/crop/index.ts: 23 <img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-21_17-56-51.png?version=1&amp;modificationDate=1755770211000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-21_17-56-51.png">kaf: 201.4不处理</p><h2 id="mj-base内部toast组件mj-base-ui和tools-ui的解析性能对比" tabindex="-1">mj-base内部toast组件mj-base-ui和tools-ui的解析性能对比 <a class="header-anchor" href="#mj-base内部toast组件mj-base-ui和tools-ui的解析性能对比" aria-label="Permalink to &quot;mj-base内部toast组件mj-base-ui和tools-ui的解析性能对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>不同组件</th><th></th></tr></thead><tbody><tr><td>case-1fontLoadManager</td><td><strong>mj-base-ui****113ms</strong></td><td><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_14-11-4.png?version=1&amp;modificationDate=1755843065000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_14-11-4.png"></td></tr><tr><td><strong>tools-ui****18.8ms</strong></td><td><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_14-55-47.png?version=1&amp;modificationDate=1755845748000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_14-55-47.png"></td><td></td></tr><tr><td><strong>None****19.4ms</strong>(这里数值是本地测的有波动, 所以可能会比上面的大些)</td><td><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_14-29-7.png?version=1&amp;modificationDate=1755844147000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_14-29-7.png"></td><td></td></tr><tr><td>case-2deleteCommand</td><td>mj-base-ui191.5ms</td><td><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_15-20-41.png?version=1&amp;modificationDate=1755847242000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_15-20-41.png"></td></tr><tr><td><strong>tools-ui****118.8ms</strong></td><td><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_15-59-8.png?version=1&amp;modificationDate=1755849549000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_15-59-8.png"></td><td></td></tr><tr><td>muya-ui153.3ms</td><td><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_15-42-39.png?version=1&amp;modificationDate=1755848560000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_15-42-39.png"></td><td></td></tr><tr><td>综上, 最后这mj-base里面还是使用tools-ui来进行消息提示</td><td></td><td></td></tr></tbody></table><p>-------------------------- Below is Draft.... --------------------------</p><p>处理前</p><p><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_11-39-47.png?version=1&amp;modificationDate=1755833987000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_11-39-47.png"></p><p>在verifyElement中直接不调用该方法</p><p><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_14-6-34.png?version=1&amp;modificationDate=1755842795000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_14-6-34.png"></p><p><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_14-11-4.png?version=1&amp;modificationDate=1755843065000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_14-11-4.png"></p><p><img src="https://cf.qunhequnhe.com/download/attachments/81282631507/image2025-8-22_11-38-28.png?version=1&amp;modificationDate=1755833909000&amp;api=v2" alt="闰土 &gt; Lite工具性能优化 &gt; image2025-8-22_11-38-28.png"></p><p>目前是156ms</p>',31)])])}const l=a(o,[["render",m]]);export{h as __pageData,l as default};
